remediation_terraform:
resource "google_compute_instance" "default" {
  # Ensure network_interface does NOT contain an access_config block
  network_interface {
    network = "default"
    # Omit access_config to disable public IP
  }
}

resource "google_compute_firewall" "ssh_rule" {
  name    = "allow-ssh"
  network = "default"

  allow {
    protocol = "tcp"
    ports    = ["22"]
  }

  source_ranges = ["35.235.240.0/20"] # Allow IAP only
}

resource "google_project_iam_member" "least_privilege" {
  project = "my-project-id"
  role    = "roles/storage.objectViewer" # Use specific predefined role instead of roles/editor
  member  = "serviceAccount:my-sa@my-project.iam.gserviceaccount.com"
}

# Recommendation: Remove google_service_account_key blocks and migrate to Workload Identity Federation
# For external workloads, use:
# resource "google_iam_workload_identity_pool" "example" { ... }
# resource "google_iam_workload_identity_pool_provider" "example" { ... }

resource "google_compute_instance" "default" {
  # 1. Remove public IP
  network_interface {
    network = "default"
  }
  # 2. Attach a least-privilege service account
  service_account {
    email  = google_service_account.least_privilege.email
    scopes = ["cloud-platform"]
  }
}
